python - <<'EOF'
import re
p = "catalog/service.py"
s = open(p).read()

s = s.replace('''from __future__ import annotations

_ALLOWED_FIELDS''', '''from __future__ import annotations

import json

_ALLOWED_FIELDS''')

s = s.replace('''    def list(self) -> list[dict]:
        return [dict(record) for record in self._records.values()]
''', '''    def list(self) -> list[dict]:
        return [dict(record) for record in self._records.values()]

    def find(self, substring: str) -> list[dict]:
        """Records whose title contains ``substring`` (case-insensitive), in creation order."""
        needle = substring.casefold()
        return [
            dict(record)
            for record in self._records.values()
            if needle in record["title"].casefold()
        ]

    def export(self) -> str:
        """Serialise all records as a JSON array, in creation order."""
        return json.dumps(self.list())

    def import_(self, dump: str) -> None:
        """Load records from an ``export()`` dump, keeping their ids.

        Works on an empty or a populated catalog. Raises ``ValueError`` if the
        dump is malformed or if any imported id is already present, in which
        case the catalog is left unchanged.
        """
        try:
            data = json.loads(dump)
        except json.JSONDecodeError as exc:
            raise ValueError(f"invalid catalog dump: {exc}") from None
        if not isinstance(data, list):
            raise ValueError("invalid catalog dump: expected a JSON array of records")

        incoming: dict[str, dict] = {}
        for item in data:
            if (
                not isinstance(item, dict)
                or set(item) != {"id", "title", "author"}
                or not all(isinstance(item[k], str) for k in ("id", "title", "author"))
            ):
                raise ValueError(f"invalid catalog dump: malformed record {item!r}")
            record_id = item["id"]
            if record_id in self._records or record_id in incoming:
                raise ValueError(f"invalid catalog dump: duplicate record id {record_id!r}")
            incoming[record_id] = {"id": record_id, "title": item["title"], "author": item["author"]}

        # Validation passed; now commit. Advance the counter past any numeric
        # imported id so future create() calls never reuse an imported id.
        for record_id, record in incoming.items():
            self._records[record_id] = record
            if record_id.isdigit():
                self._next_id = max(self._next_id, int(record_id) + 1)
''')
open(p, "w").write(s)
EOF
python -m pytest -q 2>&1 | tail -3 && python - <<'EOF'
from catalog.service import Catalog
c = Catalog(); c.create("A","x"); c.create("B","y")
d = Catalog(); d.import_(c.export()); nid = d.create("C","z")
assert nid == "3", nid
e = Catalog(); e.create("Q","q")
try: e.import_(c.export()); raise SystemExit("expected collision error")
except ValueError as err: print("collision ok:", err)
assert e.list() == [{"id":"1","title":"Q","author":"q"}]
print("extra checks ok")
EOF

